import { Console, Effect } from "effect"
import { Argument, Command, Flag } from "effect/unstable/cli"
import { MetricsClient } from "../services/MetricsClient.js"

const host = Flag.string("host").pipe(Flag.withDefault("all"))
const minutes = Flag.integer("minutes").pipe(Flag.withDefault(60))
const limit = Flag.integer("limit").pipe(Flag.withDefault(100))

const metric = Argument.choice("metric", ["cpu", "memory", "disk"])

const query = Command.make(
  "query",
  { metric, host, minutes, limit },
  ({ metric, host, minutes, limit }) =>
    Effect.gen(function*() {
      const client = yield* MetricsClient
      const samples = yield* client.querySamples({
        metric,
        host,
        minutes,
        limit
      })
      yield* Console.log(JSON.stringify(samples, null, 2))
    })
)

export const telemetry = Command.make("telemetry").pipe(
  Command.withDescription("Query host telemetry samples"),
  Command.withSubcommands([query])
)
